const OVERLAY_MODULE_KT = "package com.comfortableai.torncopilot\n\nimport android.content.Context\nimport android.content.Intent\nimport android.net.Uri\nimport android.os.Build\nimport android.provider.Settings\nimport androidx.core.content.ContextCompat\nimport com.facebook.react.bridge.Promise\nimport com.facebook.react.bridge.ReactApplicationContext\nimport com.facebook.react.bridge.ReactContextBaseJavaModule\nimport com.facebook.react.bridge.ReactMethod\n\nclass ComfortableOverlayModule(private val appContext: ReactApplicationContext) : ReactContextBaseJavaModule(appContext) {\n  override fun getName(): String = \"ComfortableOverlay\"\n\n  @ReactMethod\n  fun hasPermission(promise: Promise) {\n    promise.resolve(Build.VERSION.SDK_INT < Build.VERSION_CODES.M || Settings.canDrawOverlays(appContext))\n  }\n\n  @ReactMethod\n  fun requestPermission(promise: Promise) {\n    if (Build.VERSION.SDK_INT < Build.VERSION_CODES.M || Settings.canDrawOverlays(appContext)) {\n      promise.resolve(true)\n      return\n    }\n    try {\n      val intent = Intent(\n        Settings.ACTION_MANAGE_OVERLAY_PERMISSION,\n        Uri.parse(\"package:${appContext.packageName}\")\n      ).apply { addFlags(Intent.FLAG_ACTIVITY_NEW_TASK) }\n      appContext.startActivity(intent)\n      promise.resolve(false)\n    } catch (e: Exception) {\n      promise.reject(\"OVERLAY_SETTINGS\", \"Unable to open Android overlay settings.\", e)\n    }\n  }\n\n  @ReactMethod\n  fun startHud(apiKey: String, promise: Promise) {\n    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M && !Settings.canDrawOverlays(appContext)) {\n      promise.reject(\"OVERLAY_PERMISSION\", \"Display over other apps permission is required.\")\n      return\n    }\n    if (apiKey.isBlank()) {\n      promise.reject(\"API_KEY\", \"A Torn API key is required.\")\n      return\n    }\n    try {\n      val intent = Intent(appContext, ComfortableOverlayService::class.java).apply {\n        action = ComfortableOverlayService.ACTION_START\n        putExtra(ComfortableOverlayService.EXTRA_API_KEY, apiKey)\n      }\n      ContextCompat.startForegroundService(appContext, intent)\n      promise.resolve(true)\n    } catch (e: Exception) {\n      promise.reject(\"HUD_START\", \"Unable to start TornPulse HUD.\", e)\n    }\n  }\n\n  @ReactMethod\n  fun stopHud(promise: Promise) {\n    try {\n      val intent = Intent(appContext, ComfortableOverlayService::class.java).apply {\n        action = ComfortableOverlayService.ACTION_STOP\n      }\n      appContext.startService(intent)\n      promise.resolve(true)\n    } catch (e: Exception) {\n      promise.reject(\"HUD_STOP\", \"Unable to stop TornPulse HUD.\", e)\n    }\n  }\n\n  @ReactMethod\n  fun setHudPreferences(\n    attackAlerts: Boolean,\n    hudPreset: String,\n    hudOpacity: Double,\n    showTctClock: Boolean,\n    showHourCountdown: Boolean,\n    showBarTimers: Boolean,\n    showCooldowns: Boolean,\n    promise: Promise\n  ) {\n    try {\n      val preset = when (hudPreset.lowercase()) {\n        \"compact\" -> \"compact\"\n        \"large\" -> \"large\"\n        else -> \"standard\"\n      }\n      appContext.getSharedPreferences(\"comfortable_hud\", Context.MODE_PRIVATE)\n        .edit()\n        .putBoolean(\"attack_alerts\", attackAlerts)\n        .putString(\"hud_preset\", preset)\n        .putFloat(\"hud_opacity\", hudOpacity.coerceIn(0.45, 1.0).toFloat())\n        .putBoolean(\"show_tct_clock\", showTctClock)\n        .putBoolean(\"show_hour_countdown\", showHourCountdown)\n        .putBoolean(\"show_bar_timers\", showBarTimers)\n        .putBoolean(\"show_cooldowns\", showCooldowns)\n        .apply()\n      if (ComfortableOverlayService.isRunning) {\n        appContext.startService(Intent(appContext, ComfortableOverlayService::class.java).apply {\n          action = ComfortableOverlayService.ACTION_UPDATE_PREFS\n        })\n      }\n      promise.resolve(true)\n    } catch (e: Exception) {\n      promise.reject(\"HUD_PREFS\", \"Unable to update TornPulse HUD preferences.\", e)\n    }\n  }\n\n  @ReactMethod\n  fun getHudPositionLocked(promise: Promise) {\n    val locked = appContext.getSharedPreferences(\"comfortable_hud\", Context.MODE_PRIVATE)\n      .getBoolean(\"locked\", false)\n    promise.resolve(locked)\n  }\n\n  @ReactMethod\n  fun setHudPositionLocked(locked: Boolean, promise: Promise) {\n    try {\n      appContext.getSharedPreferences(\"comfortable_hud\", Context.MODE_PRIVATE)\n        .edit()\n        .putBoolean(\"locked\", locked)\n        .apply()\n      if (ComfortableOverlayService.isRunning) {\n        appContext.startService(Intent(appContext, ComfortableOverlayService::class.java).apply {\n          action = ComfortableOverlayService.ACTION_UPDATE_PREFS\n        })\n      }\n      promise.resolve(true)\n    } catch (e: Exception) {\n      promise.reject(\"HUD_LOCK\", \"Unable to update TornPulse HUD lock state.\", e)\n    }\n  }\n\n  @ReactMethod\n  fun resetHudPosition(promise: Promise) {\n    try {\n      appContext.getSharedPreferences(\"comfortable_hud\", Context.MODE_PRIVATE)\n        .edit()\n        .remove(\"x\")\n        .remove(\"y\")\n        .putBoolean(\"locked\", false)\n        .apply()\n      if (ComfortableOverlayService.isRunning) {\n        appContext.startService(Intent(appContext, ComfortableOverlayService::class.java).apply {\n          action = ComfortableOverlayService.ACTION_RESET_POSITION\n        })\n      }\n      promise.resolve(true)\n    } catch (e: Exception) {\n      promise.reject(\"HUD_RESET\", \"Unable to reset TornPulse HUD position.\", e)\n    }\n  }\n\n  @ReactMethod\n  fun isRunning(promise: Promise) {\n    promise.resolve(ComfortableOverlayService.isRunning)\n  }\n}\n";
const OVERLAY_SERVICE_KT = "package com.comfortableai.torncopilot\n\nimport android.app.NotificationChannel\nimport android.app.NotificationManager\nimport android.app.PendingIntent\nimport android.app.Service\nimport android.content.Context\nimport android.content.Intent\nimport android.content.pm.ServiceInfo\nimport android.graphics.Color\nimport android.graphics.PixelFormat\nimport android.graphics.Typeface\nimport android.graphics.drawable.GradientDrawable\nimport android.os.Build\nimport android.os.Handler\nimport android.os.IBinder\nimport android.os.Looper\nimport android.os.SystemClock\nimport android.text.Spannable\nimport android.text.SpannableString\nimport android.text.TextPaint\nimport android.text.TextUtils\nimport android.text.style.CharacterStyle\nimport android.text.style.ForegroundColorSpan\nimport android.text.style.UpdateAppearance\nimport android.view.Gravity\nimport android.view.HapticFeedbackConstants\nimport android.view.MotionEvent\nimport android.view.View\nimport android.view.WindowManager\nimport android.widget.ImageView\nimport android.widget.LinearLayout\nimport android.widget.TextView\nimport androidx.core.app.NotificationCompat\nimport androidx.core.app.ServiceCompat\nimport org.json.JSONObject\nimport java.net.HttpURLConnection\nimport java.net.URL\nimport java.util.concurrent.Executors\nimport java.util.concurrent.ScheduledFuture\nimport java.util.concurrent.TimeUnit\nimport kotlin.math.abs\nimport kotlin.math.max\nimport kotlin.math.min\n\nclass ComfortableOverlayService : Service() {\n  private class GlowSpan(private val radius: Float, private val glowColor: Int) : CharacterStyle(), UpdateAppearance {\n    override fun updateDrawState(tp: TextPaint) {\n      tp.setShadowLayer(radius, 0f, 0f, glowColor)\n    }\n  }\n\n  companion object {\n    const val ACTION_START = \"com.comfortableai.torncopilot.START_HUD\"\n    const val ACTION_STOP = \"com.comfortableai.torncopilot.STOP_HUD\"\n    const val ACTION_UPDATE_PREFS = \"com.comfortableai.torncopilot.UPDATE_HUD_PREFS\"\n    const val ACTION_RESET_POSITION = \"com.comfortableai.torncopilot.RESET_HUD_POSITION\"\n    const val EXTRA_API_KEY = \"comfortable_api_key\"\n    private const val CHANNEL_ID = \"comfortable-hud\"\n    private const val ATTACK_CHANNEL_ID = \"tornpulse-attack-alerts\"\n    private const val NOTIFICATION_ID = 606\n    private const val ATTACK_NOTIFICATION_BASE = 9000\n    @Volatile var isRunning: Boolean = false\n  }\n\n  private data class BarState(\n    val current: Int,\n    val maximum: Int,\n    val increment: Int,\n    val interval: Int,\n    val tickTime: Int,\n    val fullTime: Int,\n  )\n\n  private data class AttackState(\n    val id: Long,\n    val result: String,\n    val attackerName: String?,\n    val isStealthed: Boolean,\n    val ended: Long,\n  )\n\n  private data class Snapshot(\n    val life: BarState,\n    val energy: BarState,\n    val nerve: BarState,\n    val drug: Int,\n    val booster: Int,\n    val medical: Int,\n    val statusState: String,\n    val statusDescription: String,\n    val statusUntil: Long,\n    val attackAccess: Boolean,\n    val latestAttack: AttackState?,\n    val receivedElapsed: Long,\n  )\n\n  private val handler = Handler(Looper.getMainLooper())\n  private val executor = Executors.newSingleThreadScheduledExecutor()\n  private var pollFuture: ScheduledFuture<*>? = null\n  private var apiKey: String? = null\n  @Volatile private var snapshot: Snapshot? = null\n  @Volatile private var lastError: String? = null\n  private var attackBaselineReady = false\n  private var lastSeenAttackId = 0L\n  private var statusBaselineReady = false\n  private var lastStatusState = \"\"\n  private var eventTickerMessage: String? = null\n  private var eventTickerColor: Int = Color.rgb(227, 83, 96)\n  private var eventTickerUntilElapsed = 0L\n\n  private lateinit var windowManager: WindowManager\n  private var overlayView: LinearLayout? = null\n  private var headerRowView: LinearLayout? = null\n  private var accentRailView: View? = null\n  private var logoViewRef: ImageView? = null\n  private var statusText: TextView? = null\n  private var collapseText: TextView? = null\n  private var statsRow: LinearLayout? = null\n  private var lifeValueText: TextView? = null\n  private var energyValueText: TextView? = null\n  private var nerveValueText: TextView? = null\n  private var lifeCooldownText: TextView? = null\n  private var energyCooldownText: TextView? = null\n  private var nerveCooldownText: TextView? = null\n  private var cooldownRowView: LinearLayout? = null\n  private var drugCooldownText: TextView? = null\n  private var boosterCooldownText: TextView? = null\n  private var medicalCooldownText: TextView? = null\n  private var tornClockRowView: LinearLayout? = null\n  private var tornClockTimeText: TextView? = null\n  private var tornHourCountdownText: TextView? = null\n  @Volatile private var tornServerEpochSeconds = 0L\n  @Volatile private var tornServerSyncElapsed = 0L\n  private var cooldownText: TextView? = null\n  private var eventTickerText: TextView? = null\n  private var detailText: TextView? = null\n  private var params: WindowManager.LayoutParams? = null\n  private var expanded = false\n  private var positionLocked = false\n  private var hudCollapsed = false\n  private var compactHud = false\n  private var hudOpacityLevel = 0.92f\n  private var showTctClock = true\n  private var showHourCountdown = true\n  private var showBarTimers = true\n  private var showCooldownStrip = true\n  private var currentMinWidthDp = 238\n  private var currentCollapsedWidthDp = 170\n\n  private val ticker = object : Runnable {\n    override fun run() {\n      render()\n      handler.postDelayed(this, 1000)\n    }\n  }\n\n  override fun onCreate() {\n    super.onCreate()\n    windowManager = getSystemService(Context.WINDOW_SERVICE) as WindowManager\n    handler.post(ticker)\n  }\n\n  override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {\n    if (intent?.action == ACTION_STOP) {\n      stopSelf()\n      return START_NOT_STICKY\n    }\n    if (intent?.action == ACTION_UPDATE_PREFS) {\n      if (isRunning) handler.post { rebuildOverlay(true) }\n      return START_NOT_STICKY\n    }\n    if (intent?.action == ACTION_RESET_POSITION) {\n      if (isRunning) handler.post { rebuildOverlay(false) }\n      return START_NOT_STICKY\n    }\n\n    startAsForeground()\n    val incomingKey = intent?.getStringExtra(EXTRA_API_KEY)\n    if (!incomingKey.isNullOrBlank()) apiKey = incomingKey\n\n    if (apiKey.isNullOrBlank()) {\n      stopSelf()\n      return START_NOT_STICKY\n    }\n\n    try {\n      ensureOverlay()\n    } catch (_: Exception) {\n      stopSelf()\n      return START_NOT_STICKY\n    }\n\n    isRunning = true\n    startPolling()\n    return START_NOT_STICKY\n  }\n\n  override fun onBind(intent: Intent?): IBinder? = null\n\n  override fun onDestroy() {\n    isRunning = false\n    apiKey = null\n    handler.removeCallbacks(ticker)\n    pollFuture?.cancel(true)\n    executor.shutdownNow()\n    overlayView?.let {\n      try { windowManager.removeView(it) } catch (_: Exception) {}\n    }\n    overlayView = null\n    stopForeground(STOP_FOREGROUND_REMOVE)\n    super.onDestroy()\n  }\n\n  private fun startAsForeground() {\n    val manager = getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager\n    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {\n      manager.createNotificationChannel(\n        NotificationChannel(CHANNEL_ID, \"TornPulse HUD\", NotificationManager.IMPORTANCE_LOW).apply {\n          description = \"Keeps the TornPulse floating Torn HUD running\"\n          setShowBadge(false)\n        }\n      )\n      manager.createNotificationChannel(\n        NotificationChannel(ATTACK_CHANNEL_ID, \"TornPulse Attack Alerts\", NotificationManager.IMPORTANCE_HIGH).apply {\n          description = \"Alerts when the live TornPulse HUD detects a new incoming attack\"\n          enableVibration(true)\n          vibrationPattern = longArrayOf(0, 250, 120, 250)\n        }\n      )\n    }\n\n    val launchIntent = packageManager.getLaunchIntentForPackage(packageName)\n    val launchPending = launchIntent?.let {\n      PendingIntent.getActivity(this, 0, it, PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE)\n    }\n    val stopIntent = Intent(this, ComfortableOverlayService::class.java).apply { action = ACTION_STOP }\n    val stopPending = PendingIntent.getService(this, 1, stopIntent, PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE)\n\n    val notification = NotificationCompat.Builder(this, CHANNEL_ID)\n      .setSmallIcon(applicationInfo.icon)\n      .setContentTitle(\"TornPulse HUD is running\")\n      .setContentText(\"Health, Energy, Nerve and Torn status are staying visible.\")\n      .setOngoing(true)\n      .setOnlyAlertOnce(true)\n      .setCategory(NotificationCompat.CATEGORY_SERVICE)\n      .setPriority(NotificationCompat.PRIORITY_LOW)\n      .setContentIntent(launchPending)\n      .addAction(android.R.drawable.ic_menu_close_clear_cancel, \"Stop HUD\", stopPending)\n      .build()\n\n    if (Build.VERSION.SDK_INT >= 34) {\n      ServiceCompat.startForeground(this, NOTIFICATION_ID, notification, ServiceInfo.FOREGROUND_SERVICE_TYPE_SPECIAL_USE)\n    } else {\n      startForeground(NOTIFICATION_ID, notification)\n    }\n  }\n\n  private fun ensureOverlay() {\n    if (overlayView != null) return\n\n    val prefs = getSharedPreferences(\"comfortable_hud\", Context.MODE_PRIVATE)\n    hudOpacityLevel = prefs.getFloat(\"hud_opacity\", 0.92f).coerceIn(0.45f, 1.0f)\n    showTctClock = prefs.getBoolean(\"show_tct_clock\", true)\n    showHourCountdown = prefs.getBoolean(\"show_hour_countdown\", true)\n    showBarTimers = prefs.getBoolean(\"show_bar_timers\", true)\n    showCooldownStrip = prefs.getBoolean(\"show_cooldowns\", true)\n    val preset = prefs.getString(\"hud_preset\", \"standard\") ?: \"standard\"\n    val compact = preset == \"compact\"\n    val large = preset == \"large\"\n    val minWidthDp = when {\n      compact -> 202\n      large -> 280\n      else -> 238\n    }\n    val collapsedWidthDp = when {\n      compact -> 38\n      large -> 50\n      else -> 44\n    }\n    hudCollapsed = prefs.getBoolean(\"hud_collapsed\", false)\n    compactHud = compact\n    currentMinWidthDp = minWidthDp\n    currentCollapsedWidthDp = collapsedWidthDp\n    val horizontalPadding = when {\n      compact -> 6\n      large -> 10\n      else -> 8\n    }\n    val verticalPadding = when {\n      compact -> 3\n      large -> 6\n      else -> 4\n    }\n    val headerSize = when {\n      compact -> 7f\n      large -> 9f\n      else -> 8f\n    }\n    val logoSize = when {\n      compact -> 18\n      large -> 24\n      else -> 21\n    }\n    val statLabelSize = when {\n      compact -> 7f\n      large -> 9f\n      else -> 8f\n    }\n    val barsSize = when {\n      compact -> 13f\n      large -> 19f\n      else -> 16f\n    }\n    val cooldownSize = when {\n      compact -> 7f\n      large -> 9f\n      else -> 8f\n    }\n    val tickerSize = when {\n      compact -> 7f\n      large -> 9f\n      else -> 8f\n    }\n    val detailSize = when {\n      compact -> 8f\n      large -> 10f\n      else -> 9f\n    }\n\n    val root = LinearLayout(this).apply {\n      orientation = LinearLayout.VERTICAL\n      setPadding(dp(horizontalPadding), dp(verticalPadding), dp(horizontalPadding), dp(verticalPadding))\n      minimumWidth = dp(if (hudCollapsed) collapsedWidthDp else minWidthDp)\n      elevation = dp(14).toFloat()\n      alpha = hudOpacityLevel\n      background = GradientDrawable(\n        GradientDrawable.Orientation.TOP_BOTTOM,\n        intArrayOf(Color.rgb(77, 80, 83), Color.rgb(54, 57, 60))\n      ).apply {\n        shape = GradientDrawable.RECTANGLE\n        cornerRadius = dp(12).toFloat()\n      }\n    }\n\n    val accentRail = View(this).apply {\n      setBackgroundColor(Color.argb(85, 225, 228, 231))\n      visibility = if (hudCollapsed) View.GONE else View.VISIBLE\n    }\n    accentRailView = accentRail\n    root.addView(accentRail, LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, dp(1)).apply { bottomMargin = dp(6) })\n\n    val headerRow = LinearLayout(this).apply {\n      orientation = LinearLayout.HORIZONTAL\n      gravity = if (hudCollapsed) Gravity.CENTER else Gravity.CENTER_VERTICAL\n    }\n    headerRowView = headerRow\n    val logoView = ImageView(this).apply {\n      setImageDrawable(applicationInfo.loadIcon(packageManager))\n      scaleType = ImageView.ScaleType.FIT_CENTER\n      contentDescription = if (hudCollapsed) \"Expand TornPulse HUD\" else \"Collapse TornPulse HUD\"\n    }\n    logoViewRef = logoView\n    headerRow.addView(logoView, LinearLayout.LayoutParams(dp(logoSize), dp(logoSize)))\n    statusText = makeText(\"CONNECTING\", headerSize, Color.rgb(176, 183, 193), true).also {\n      it.letterSpacing = 0.12f\n      it.setPadding(dp(8), 0, 0, 0)\n      it.textAlignment = View.TEXT_ALIGNMENT_VIEW_END\n      it.visibility = if (hudCollapsed) View.GONE else View.VISIBLE\n      headerRow.addView(it, LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1f))\n    }\n    root.addView(headerRow, LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT))\n\n    val tornClockRow = LinearLayout(this).apply {\n      orientation = LinearLayout.HORIZONTAL\n      gravity = Gravity.CENTER_VERTICAL\n      setPadding(dp(6), dp(4), dp(6), dp(4))\n      visibility = if (hudCollapsed || (!showTctClock && !showHourCountdown)) View.GONE else View.VISIBLE\n      background = GradientDrawable().apply {\n        shape = GradientDrawable.RECTANGLE\n        cornerRadius = dp(6).toFloat()\n        setColor(Color.argb(96, 27, 29, 32))\n        setStroke(dp(1), Color.argb(64, 220, 223, 226))\n      }\n    }\n    tornClockTimeText = makeText(\"TCT  --:--:--\", cooldownSize, Color.rgb(190, 195, 200), true).also {\n      it.maxLines = 1\n      it.visibility = if (showTctClock) View.VISIBLE else View.GONE\n      tornClockRow.addView(it, LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1f))\n    }\n    tornHourCountdownText = makeText(\"HOUR  --:--:--\", cooldownSize + 1f, Color.rgb(244, 245, 246), true).also {\n      it.maxLines = 1\n      it.visibility = if (showHourCountdown) View.VISIBLE else View.GONE\n      it.textAlignment = View.TEXT_ALIGNMENT_VIEW_END\n      tornClockRow.addView(it, LinearLayout.LayoutParams(LinearLayout.LayoutParams.WRAP_CONTENT, LinearLayout.LayoutParams.WRAP_CONTENT))\n    }\n    tornClockRowView = tornClockRow\n    root.addView(tornClockRow, LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT).apply {\n      topMargin = dp(5)\n    })\n\n    val statContainer = LinearLayout(this).apply {\n      orientation = LinearLayout.HORIZONTAL\n      gravity = Gravity.CENTER\n      setPadding(0, dp(5), 0, dp(1))\n      visibility = if (hudCollapsed) View.GONE else View.VISIBLE\n    }\n    fun makeStatColumn(label: String, color: Int): Triple<LinearLayout, TextView, TextView> {\n      val column = LinearLayout(this).apply {\n        orientation = LinearLayout.VERTICAL\n        gravity = Gravity.CENTER\n      }\n      val miniRow = LinearLayout(this).apply {\n        orientation = LinearLayout.HORIZONTAL\n        gravity = Gravity.CENTER\n      }\n      val labelView = makeText(label, statLabelSize + 1f, color, true).apply {\n        letterSpacing = 0.08f\n      }\n      val timerView = makeText(\"--\", maxOf(6f, statLabelSize - 1f), Color.rgb(188, 193, 200), true).apply {\n        setPadding(dp(4), 0, 0, 0)\n        visibility = if (showBarTimers) View.VISIBLE else View.GONE\n        maxLines = 1\n      }\n      miniRow.addView(labelView)\n      miniRow.addView(timerView)\n      val valueView = makeText(\"-- / --\", barsSize, Color.rgb(244, 245, 246), true).apply {\n        setPadding(0, dp(1), 0, 0)\n        maxLines = 1\n        textAlignment = View.TEXT_ALIGNMENT_CENTER\n      }\n      column.addView(miniRow, LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT))\n      column.addView(valueView, LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT))\n      return Triple(column, valueView, timerView)\n    }\n    val lifeStat = makeStatColumn(\"H\", Color.rgb(52, 152, 219))\n    val energyStat = makeStatColumn(\"E\", Color.rgb(103, 213, 45))\n    val nerveStat = makeStatColumn(\"N\", Color.rgb(255, 90, 56))\n    statContainer.addView(lifeStat.first, LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1f))\n    statContainer.addView(energyStat.first, LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1f))\n    statContainer.addView(nerveStat.first, LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1f))\n    lifeValueText = lifeStat.second\n    energyValueText = energyStat.second\n    nerveValueText = nerveStat.second\n    lifeCooldownText = lifeStat.third\n    energyCooldownText = energyStat.third\n    nerveCooldownText = nerveStat.third\n    statsRow = statContainer\n    root.addView(statContainer, LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT))\n\n    val cooldownRow = LinearLayout(this).apply {\n      orientation = LinearLayout.HORIZONTAL\n      gravity = Gravity.CENTER\n      visibility = if (hudCollapsed || !showCooldownStrip) View.GONE else View.VISIBLE\n    }\n    fun makeCooldownChip(label: String, labelColor: Int): Pair<LinearLayout, TextView> {\n      val chip = LinearLayout(this).apply {\n        orientation = LinearLayout.VERTICAL\n        gravity = Gravity.CENTER\n        setPadding(dp(4), dp(4), dp(4), dp(4))\n        background = GradientDrawable().apply {\n          shape = GradientDrawable.RECTANGLE\n          cornerRadius = dp(6).toFloat()\n          setColor(Color.argb(118, 31, 33, 36))\n          setStroke(dp(1), Color.argb(72, 220, 223, 226))\n        }\n      }\n      val labelView = makeText(label, maxOf(6f, cooldownSize - 1f), labelColor, true).apply {\n        letterSpacing = 0.06f\n        maxLines = 1\n        textAlignment = View.TEXT_ALIGNMENT_CENTER\n      }\n      val valueView = makeText(\"--\", cooldownSize, Color.rgb(236, 238, 240), true).apply {\n        setPadding(0, dp(1), 0, 0)\n        maxLines = 1\n        textAlignment = View.TEXT_ALIGNMENT_CENTER\n      }\n      chip.addView(labelView, LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT))\n      chip.addView(valueView, LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT))\n      return Pair(chip, valueView)\n    }\n    val drugChip = makeCooldownChip(\"💊\", Color.rgb(180, 184, 205))\n    val boosterChip = makeCooldownChip(\"🥤\", Color.rgb(215, 165, 68))\n    val medicalChip = makeCooldownChip(\"✚\", Color.rgb(111, 208, 141))\n    cooldownRow.addView(drugChip.first, LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1f).apply { rightMargin = dp(3) })\n    cooldownRow.addView(boosterChip.first, LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1f).apply { leftMargin = dp(1); rightMargin = dp(1) })\n    cooldownRow.addView(medicalChip.first, LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1f).apply { leftMargin = dp(3) })\n    drugCooldownText = drugChip.second\n    boosterCooldownText = boosterChip.second\n    medicalCooldownText = medicalChip.second\n    cooldownRowView = cooldownRow\n    root.addView(cooldownRow, LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT).apply {\n      topMargin = dp(5)\n    })\n\n    eventTickerText = makeText(\"\", tickerSize + 1f, Color.rgb(244, 245, 246), true).also {\n      it.setPadding(dp(8), dp(6), dp(8), dp(6))\n      it.maxLines = 2\n      it.visibility = View.GONE\n      root.addView(it, LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT).apply {\n        topMargin = dp(6)\n      })\n    }\n\n    positionLocked = prefs.getBoolean(\"locked\", false)\n    val display = resources.displayMetrics\n    val savedX = prefs.getInt(\"x\", dp(12))\n    val savedY = prefs.getInt(\"y\", dp(120))\n    val type = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY else WindowManager.LayoutParams.TYPE_PHONE\n\n    val lp = WindowManager.LayoutParams(\n      WindowManager.LayoutParams.WRAP_CONTENT,\n      WindowManager.LayoutParams.WRAP_CONTENT,\n      type,\n      WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,\n      PixelFormat.TRANSLUCENT\n    ).apply {\n      gravity = Gravity.TOP or Gravity.START\n      x = min(max(0, savedX), max(0, display.widthPixels - dp(if (hudCollapsed) collapsedWidthDp else minWidthDp)))\n      y = max(dp(36), savedY)\n    }\n\n    var initialX = 0\n    var initialY = 0\n    var initialTouchX = 0f\n    var initialTouchY = 0f\n    var touchDownElapsed = 0L\n    var moved = false\n\n    root.setOnTouchListener { _, event ->\n      when (event.actionMasked) {\n        MotionEvent.ACTION_DOWN -> {\n          initialX = lp.x\n          initialY = lp.y\n          initialTouchX = event.rawX\n          initialTouchY = event.rawY\n          touchDownElapsed = SystemClock.elapsedRealtime()\n          moved = false\n          true\n        }\n        MotionEvent.ACTION_MOVE -> {\n          val dx = event.rawX - initialTouchX\n          val dy = event.rawY - initialTouchY\n          if (!positionLocked && (abs(dx) > dp(4) || abs(dy) > dp(4))) moved = true\n          if (moved && !positionLocked) {\n            val width = max(root.width, dp(if (hudCollapsed) collapsedWidthDp else minWidthDp))\n            val height = max(root.height, dp(60))\n            lp.x = min(max(0, initialX + dx.toInt()), max(0, display.widthPixels - width))\n            lp.y = min(max(dp(30), initialY + dy.toInt()), max(dp(30), display.heightPixels - height - dp(30)))\n            try { windowManager.updateViewLayout(root, lp) } catch (_: Exception) {}\n          }\n          true\n        }\n        MotionEvent.ACTION_UP -> {\n          val heldMs = SystemClock.elapsedRealtime() - touchDownElapsed\n          if (!moved && heldMs >= 650L) {\n            positionLocked = !positionLocked\n            prefs.edit().putBoolean(\"locked\", positionLocked).apply()\n            root.performHapticFeedback(HapticFeedbackConstants.LONG_PRESS)\n            render()\n          } else if (!moved) {\n            val logoHit = hudCollapsed || (event.x <= dp(logoSize + 14) && event.y <= dp(logoSize + 14))\n            if (logoHit) {\n              hudCollapsed = !hudCollapsed\n              expanded = false\n              prefs.edit().putBoolean(\"hud_collapsed\", hudCollapsed).apply()\n              applyCollapsedState()\n              render()\n            }\n          }\n          prefs.edit().putInt(\"x\", lp.x).putInt(\"y\", lp.y).apply()\n          true\n        }\n        else -> false\n      }\n    }\n\n    windowManager.addView(root, lp)\n    overlayView = root\n    params = lp\n    render()\n  }\n\n  private fun rebuildOverlay(savePosition: Boolean) {\n    val currentParams = params\n    if (savePosition && currentParams != null) {\n      getSharedPreferences(\"comfortable_hud\", Context.MODE_PRIVATE)\n        .edit()\n        .putInt(\"x\", currentParams.x)\n        .putInt(\"y\", currentParams.y)\n        .apply()\n    }\n    overlayView?.let {\n      try { windowManager.removeView(it) } catch (_: Exception) {}\n    }\n    overlayView = null\n    headerRowView = null\n    accentRailView = null\n    logoViewRef = null\n    statusText = null\n    collapseText = null\n    statsRow = null\n    lifeValueText = null\n    energyValueText = null\n    nerveValueText = null\n    lifeCooldownText = null\n    energyCooldownText = null\n    nerveCooldownText = null\n    cooldownRowView = null\n    drugCooldownText = null\n    boosterCooldownText = null\n    medicalCooldownText = null\n    tornClockRowView = null\n    tornClockTimeText = null\n    tornHourCountdownText = null\n    cooldownText = null\n    eventTickerText = null\n    detailText = null\n    params = null\n    expanded = false\n    ensureOverlay()\n  }\n\n  private fun makeText(value: String, size: Float, color: Int, bold: Boolean): TextView =\n    TextView(this).apply {\n      text = value\n      textSize = size\n      setTextColor(color)\n      typeface = if (bold) Typeface.DEFAULT_BOLD else Typeface.DEFAULT\n      includeFontPadding = false\n    }\n\n  private fun renderBarValue(view: TextView?, current: Int, maximum: Int, color: Int) {\n    val target = view ?: return\n    if (maximum <= 0) {\n      target.text = \"-- / --\"\n      target.setTextColor(Color.rgb(137, 145, 156))\n      return\n    }\n    val white = Color.rgb(244, 245, 246)\n    val muted = Color.rgb(137, 145, 156)\n    val currentText = current.toString()\n    val maxText = maximum.toString()\n    val text = \"$currentText / $maxText\"\n    val styled = SpannableString(text)\n    val currentStart = 0\n    val currentEnd = currentText.length\n    val slashStart = currentEnd + 1\n    val slashEnd = slashStart + 1\n    val maxStart = slashEnd + 1\n    val maxEnd = maxStart + maxText.length\n    val capped = current >= maximum\n\n    styled.setSpan(ForegroundColorSpan(if (capped) color else white), currentStart, currentEnd, Spannable.SPAN_EXCLUSIVE_EXCLUSIVE)\n    styled.setSpan(GlowSpan(if (capped) dp(3).toFloat() else dp(2).toFloat(), color), currentStart, currentEnd, Spannable.SPAN_EXCLUSIVE_EXCLUSIVE)\n    styled.setSpan(ForegroundColorSpan(if (capped) color else muted), slashStart, slashEnd, Spannable.SPAN_EXCLUSIVE_EXCLUSIVE)\n    styled.setSpan(ForegroundColorSpan(color), maxStart, maxEnd, Spannable.SPAN_EXCLUSIVE_EXCLUSIVE)\n    target.text = styled\n  }\n\n  private fun renderBars(lifeCurrent: Int, lifeMax: Int, energyCurrent: Int, energyMax: Int, nerveCurrent: Int, nerveMax: Int) {\n    renderBarValue(lifeValueText, lifeCurrent, lifeMax, Color.rgb(52, 152, 219))\n    renderBarValue(energyValueText, energyCurrent, energyMax, Color.rgb(103, 213, 45))\n    renderBarValue(nerveValueText, nerveCurrent, nerveMax, Color.rgb(255, 90, 56))\n  }\n\n  private fun renderEmptyBars() {\n    lifeValueText?.text = \"-- / --\"\n    energyValueText?.text = \"-- / --\"\n    nerveValueText?.text = \"-- / --\"\n    lifeValueText?.setTextColor(Color.rgb(137, 145, 156))\n    energyValueText?.setTextColor(Color.rgb(137, 145, 156))\n    nerveValueText?.setTextColor(Color.rgb(137, 145, 156))\n  }\n\n  private fun applyCollapsedState() {\n    val root = overlayView ?: return\n    statsRow?.visibility = if (hudCollapsed) View.GONE else View.VISIBLE\n    cooldownRowView?.visibility = if (hudCollapsed || !showCooldownStrip) View.GONE else View.VISIBLE\n    tornClockRowView?.visibility = if (hudCollapsed || (!showTctClock && !showHourCountdown)) View.GONE else View.VISIBLE\n    statusText?.visibility = if (hudCollapsed) View.GONE else View.VISIBLE\n    accentRailView?.visibility = if (hudCollapsed) View.GONE else View.VISIBLE\n    headerRowView?.gravity = if (hudCollapsed) Gravity.CENTER else Gravity.CENTER_VERTICAL\n    logoViewRef?.contentDescription = if (hudCollapsed) \"Expand TornPulse HUD\" else \"Collapse TornPulse HUD\"\n    root.minimumWidth = dp(if (hudCollapsed) currentCollapsedWidthDp else currentMinWidthDp)\n    root.background = GradientDrawable(\n      GradientDrawable.Orientation.TOP_BOTTOM,\n      intArrayOf(Color.rgb(77, 80, 83), Color.rgb(54, 57, 60))\n    ).apply {\n      shape = GradientDrawable.RECTANGLE\n      cornerRadius = dp(12).toFloat()\n    }\n    if (hudCollapsed) eventTickerText?.visibility = View.GONE else renderEventTicker()\n    val lp = params\n    if (lp != null) {\n      val display = resources.displayMetrics\n      val targetWidth = dp(if (hudCollapsed) currentCollapsedWidthDp else currentMinWidthDp)\n      lp.x = min(max(0, lp.x), max(0, display.widthPixels - targetWidth))\n      try { windowManager.updateViewLayout(root, lp) } catch (_: Exception) {}\n    }\n    root.requestLayout()\n  }\n\n  private fun startPolling() {\n    if (pollFuture == null || pollFuture?.isCancelled == true) {\n      pollFuture = executor.scheduleWithFixedDelay({ fetchSnapshot() }, 0, 60, TimeUnit.SECONDS)\n    } else {\n      executor.execute { fetchSnapshot() }\n    }\n  }\n\n  private fun fetchSnapshot() {\n    val key = apiKey ?: return\n    try {\n      val bars = getJson(\"/user/bars\", key).getJSONObject(\"bars\")\n      val cooldowns = getJson(\"/user/cooldowns\", key).getJSONObject(\"cooldowns\")\n      val profile = getJson(\"/user/basic\", key).getJSONObject(\"profile\")\n      val status = profile.getJSONObject(\"status\")\n\n      var attackAccess = true\n      var latestAttack: AttackState? = null\n      try {\n        val attackArray = getJson(\"/user/attacks?filters=incoming&sort=DESC&limit=1\", key).optJSONArray(\"attacks\")\n        if (attackArray != null && attackArray.length() > 0) {\n          val attack = attackArray.getJSONObject(0)\n          val attacker = attack.optJSONObject(\"attacker\")\n          latestAttack = AttackState(\n            id = attack.optLong(\"id\", 0L),\n            result = attack.optString(\"result\", \"Unknown\"),\n            attackerName = attacker?.optString(\"name\")?.takeIf { it.isNotBlank() },\n            isStealthed = attack.optBoolean(\"is_stealthed\", attacker == null),\n            ended = attack.optLong(\"ended\", attack.optLong(\"started\", 0L)),\n          )\n        }\n      } catch (_: Exception) {\n        attackAccess = false\n      }\n\n      maybeNotifyAttack(latestAttack, attackAccess)\n      maybeTrackStatus(status.optString(\"state\", \"Unknown\"))\n\n      val next = Snapshot(\n        life = readBar(bars.getJSONObject(\"life\")),\n        energy = readBar(bars.getJSONObject(\"energy\")),\n        nerve = readBar(bars.getJSONObject(\"nerve\")),\n        drug = cooldowns.optInt(\"drug\", 0),\n        booster = cooldowns.optInt(\"booster\", 0),\n        medical = cooldowns.optInt(\"medical\", 0),\n        statusState = status.optString(\"state\", \"Unknown\"),\n        statusDescription = status.optString(\"description\", status.optString(\"state\", \"Unknown\")),\n        statusUntil = if (status.isNull(\"until\")) 0L else status.optLong(\"until\", 0L),\n        attackAccess = attackAccess,\n        latestAttack = latestAttack,\n        receivedElapsed = SystemClock.elapsedRealtime(),\n      )\n      snapshot = next\n      lastError = null\n      handler.post { render() }\n\n      // Sync against Torn's forum/server clock after the core snapshot is already live.\n      // A failed clock sync never takes Health/Energy/Nerve/status offline.\n      try {\n        val cacheBust = System.currentTimeMillis() / 1000L\n        val serverTime = getJson(\"/forum/timestamp?timestamp=$cacheBust\", key).optLong(\"timestamp\", 0L)\n        if (serverTime > 0L) {\n          tornServerEpochSeconds = serverTime\n          tornServerSyncElapsed = SystemClock.elapsedRealtime()\n          handler.post { renderTornClock() }\n        }\n      } catch (_: Exception) {\n        // Keep the last good Torn clock anchor if the time-only request fails.\n      }\n    } catch (e: Exception) {\n      lastError = e.message ?: \"Connection issue\"\n      handler.post { render() }\n    }\n  }\n\n  private fun getJson(path: String, key: String): JSONObject {\n    val separator = if (path.contains(\"?\")) \"&\" else \"?\"\n    val connection = URL(\"https://api.torn.com/v2$path${separator}comment=TornPulse-HUD\").openConnection() as HttpURLConnection\n    connection.connectTimeout = 12000\n    connection.readTimeout = 12000\n    connection.requestMethod = \"GET\"\n    connection.setRequestProperty(\"Authorization\", \"ApiKey $key\")\n    connection.setRequestProperty(\"Accept\", \"application/json\")\n    connection.setRequestProperty(\"User-Agent\", \"TornPulse/1.0.0\")\n    return try {\n      val code = connection.responseCode\n      val stream = if (code in 200..299) connection.inputStream else connection.errorStream\n      val body = stream?.bufferedReader()?.use { it.readText() } ?: \"{}\"\n      val json = JSONObject(body)\n      if (code !in 200..299 || json.has(\"error\")) {\n        val error = json.optJSONObject(\"error\")\n        throw IllegalStateException(error?.optString(\"error\") ?: error?.optString(\"message\") ?: \"Torn API error ($code)\")\n      }\n      json\n    } finally {\n      connection.disconnect()\n    }\n  }\n\n  private fun readBar(json: JSONObject): BarState {\n    val bar = BarState(\n      current = json.optInt(\"current\", 0),\n      maximum = json.optInt(\"maximum\", 0),\n      increment = json.optInt(\"increment\", 0),\n      interval = json.optInt(\"interval\", 0),\n      tickTime = max(0, json.optInt(\"tick_time\", 0)),\n      fullTime = max(0, json.optInt(\"full_time\", 0)),\n    )\n    if (bar.maximum <= 0) throw IllegalStateException(\"Invalid Torn bar response\")\n    return bar\n  }\n\n  private fun projected(bar: BarState, elapsed: Int): Int {\n    if (bar.current >= bar.maximum) return bar.maximum\n    if (bar.interval <= 0 || bar.increment <= 0) return bar.current\n    val firstTick = if (bar.tickTime > 0) bar.tickTime else bar.interval\n    if (elapsed < firstTick) return bar.current\n    val ticks = 1 + (elapsed - firstTick) / bar.interval\n    return min(bar.maximum, bar.current + ticks * bar.increment)\n  }\n\n  private fun remaining(initial: Int, elapsed: Int): Int = max(0, initial - elapsed)\n\n  private fun render() {\n    renderTornClock()\n    val snap = snapshot\n    if (snap == null) {\n      statusText?.text = if (lastError == null) \"CONNECTING\" else \"OFFLINE\"\n      statusText?.setTextColor(if (lastError == null) Color.rgb(176, 183, 193) else Color.rgb(227, 83, 96))\n      renderEmptyBars()\n      lifeCooldownText?.text = \"--\"\n      energyCooldownText?.text = \"--\"\n      nerveCooldownText?.text = \"--\"\n      renderCooldownStrip(-1, -1, -1)\n      renderEventTicker()\n      return\n    }\n\n    val elapsed = max(0, ((SystemClock.elapsedRealtime() - snap.receivedElapsed) / 1000L).toInt())\n    val life = projected(snap.life, elapsed)\n    val energy = projected(snap.energy, elapsed)\n    val nerve = projected(snap.nerve, elapsed)\n    val stale = elapsed > 120 || lastError != null\n    val nowUnix = currentTornEpochSeconds() ?: (System.currentTimeMillis() / 1000L)\n    val statusRemaining = if (snap.statusUntil > nowUnix) (snap.statusUntil - nowUnix).toInt() else 0\n    val state = snap.statusState.ifBlank { \"Unknown\" }.uppercase()\n    val headerStatus = if (statusRemaining > 0) \"$state ${formatDuration(statusRemaining)}\" else state\n    val lockMark = if (positionLocked) \" • 🔒\" else \"\"\n\n    statusText?.text = if (stale) \"CHECKING$lockMark\" else \"$headerStatus$lockMark\"\n    val statusColor = when {\n      stale -> Color.rgb(225, 168, 52)\n      state.contains(\"OKAY\") -> Color.rgb(97, 215, 133)\n      state.contains(\"HOSPITAL\") -> Color.rgb(227, 83, 96)\n      state.contains(\"JAIL\") -> Color.rgb(225, 168, 52)\n      else -> Color.rgb(213, 47, 50)\n    }\n    statusText?.setTextColor(statusColor)\n    renderBars(life, snap.life.maximum, energy, snap.energy.maximum, nerve, snap.nerve.maximum)\n    renderEventTicker()\n\n    val lifeFull = if (life >= snap.life.maximum) \"CAPPED\" else formatDuration(remaining(snap.life.fullTime, elapsed))\n    val energyFull = if (energy >= snap.energy.maximum) \"CAPPED\" else formatDuration(remaining(snap.energy.fullTime, elapsed))\n    val nerveFull = if (nerve >= snap.nerve.maximum) \"CAPPED\" else formatDuration(remaining(snap.nerve.fullTime, elapsed))\n    val timerMuted = Color.rgb(188, 193, 200)\n    lifeCooldownText?.apply {\n      text = lifeFull\n      setTextColor(if (life >= snap.life.maximum) Color.rgb(52, 152, 219) else timerMuted)\n    }\n    energyCooldownText?.apply {\n      text = energyFull\n      setTextColor(if (energy >= snap.energy.maximum) Color.rgb(103, 213, 45) else timerMuted)\n    }\n    nerveCooldownText?.apply {\n      text = nerveFull\n      setTextColor(if (nerve >= snap.nerve.maximum) Color.rgb(255, 90, 56) else timerMuted)\n    }\n    val drugSeconds = remaining(snap.drug, elapsed)\n    val boosterSeconds = remaining(snap.booster, elapsed)\n    val medicalSeconds = remaining(snap.medical, elapsed)\n    renderCooldownStrip(drugSeconds, boosterSeconds, medicalSeconds)\n  }\n\n  private fun maybeNotifyAttack(attack: AttackState?, attackAccess: Boolean) {\n    if (!attackAccess) return\n    if (!attackBaselineReady) {\n      attackBaselineReady = true\n      if (attack != null && attack.id > 0L) lastSeenAttackId = attack.id\n      return\n    }\n    if (attack == null || attack.id <= 0L || attack.id == lastSeenAttackId) return\n    lastSeenAttackId = attack.id\n\n    val prefs = getSharedPreferences(\"comfortable_hud\", Context.MODE_PRIVATE)\n    if (!prefs.getBoolean(\"attack_alerts\", true)) return\n\n    val who = attack.attackerName ?: if (attack.isStealthed) \"UNKNOWN / STEALTH\" else \"UNKNOWN ATTACKER\"\n    val result = attack.result.ifBlank { \"ATTACKED\" }.uppercase()\n    val tickerMessage = if (result.contains(\"MUG\")) \"MUGGED BY $who\" else \"ATTACKED BY $who • $result\"\n    showHudEvent(tickerMessage, Color.rgb(227, 83, 96), 35)\n\n    val manager = getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager\n    val launchIntent = packageManager.getLaunchIntentForPackage(packageName)\n    val launchPending = launchIntent?.let {\n      PendingIntent.getActivity(this, 2, it, PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE)\n    }\n    val notificationWho = attack.attackerName ?: if (attack.isStealthed) \"Unknown / stealth\" else \"Unknown attacker\"\n    val notification = NotificationCompat.Builder(this, ATTACK_CHANNEL_ID)\n      .setSmallIcon(applicationInfo.icon)\n      .setContentTitle(\"TornPulse • Incoming attack\")\n      .setContentText(\"$notificationWho • ${attack.result}\")\n      .setStyle(NotificationCompat.BigTextStyle().bigText(\"$notificationWho • ${attack.result}\"))\n      .setPriority(NotificationCompat.PRIORITY_HIGH)\n      .setCategory(NotificationCompat.CATEGORY_EVENT)\n      .setAutoCancel(true)\n      .setContentIntent(launchPending)\n      .build()\n    manager.notify(ATTACK_NOTIFICATION_BASE + (attack.id % 1000L).toInt(), notification)\n  }\n\n  private fun maybeTrackStatus(newState: String) {\n    val normalized = newState.trim().uppercase()\n    if (!statusBaselineReady) {\n      statusBaselineReady = true\n      lastStatusState = normalized\n      return\n    }\n    val previous = lastStatusState\n    lastStatusState = normalized\n    if (previous.contains(\"HOSPITAL\") && !normalized.contains(\"HOSPITAL\")) {\n      showHudEvent(\"RELEASED FROM HOSPITAL\", Color.rgb(97, 215, 133), 30)\n    } else if (previous.contains(\"JAIL\") && !normalized.contains(\"JAIL\")) {\n      showHudEvent(\"RELEASED FROM JAIL\", Color.rgb(97, 215, 133), 30)\n    }\n  }\n\n  private fun showHudEvent(message: String, color: Int, seconds: Int) {\n    eventTickerMessage = message\n    eventTickerColor = color\n    eventTickerUntilElapsed = SystemClock.elapsedRealtime() + seconds * 1000L\n    handler.post { renderEventTicker() }\n  }\n\n  private fun currentTornEpochSeconds(): Long? {\n    if (tornServerEpochSeconds <= 0L || tornServerSyncElapsed <= 0L) return null\n    val elapsedSeconds = ((SystemClock.elapsedRealtime() - tornServerSyncElapsed) / 1000L).coerceAtLeast(0L)\n    return tornServerEpochSeconds + elapsedSeconds\n  }\n\n  private fun clockStamp(totalSeconds: Long): String {\n    val hours = totalSeconds / 3600L\n    val minutes = (totalSeconds % 3600L) / 60L\n    val seconds = totalSeconds % 60L\n    return hours.toString().padStart(2, '0') + \":\" +\n      minutes.toString().padStart(2, '0') + \":\" +\n      seconds.toString().padStart(2, '0')\n  }\n\n  private fun renderTornClock() {\n    val row = tornClockRowView ?: return\n    if (hudCollapsed || (!showTctClock && !showHourCountdown)) {\n      row.visibility = View.GONE\n      return\n    }\n    row.visibility = View.VISIBLE\n    tornClockTimeText?.visibility = if (showTctClock) View.VISIBLE else View.GONE\n    tornHourCountdownText?.visibility = if (showHourCountdown) View.VISIBLE else View.GONE\n    val now = currentTornEpochSeconds()\n    if (now == null) {\n      tornClockTimeText?.apply {\n        text = \"TCT  SYNCING\"\n        setTextColor(Color.rgb(190, 195, 200))\n      }\n      tornHourCountdownText?.apply {\n        text = \"HOUR  --:--:--\"\n        setTextColor(Color.rgb(190, 195, 200))\n      }\n      return\n    }\n\n    val daySeconds = ((now % 86400L) + 86400L) % 86400L\n    val secondsIntoHour = daySeconds % 3600L\n    val remaining = if (secondsIntoHour == 0L) 0L else 3600L - secondsIntoHour\n    tornClockTimeText?.apply {\n      text = \"TCT  ${clockStamp(daySeconds)}\"\n      setTextColor(Color.rgb(205, 209, 213))\n    }\n    tornHourCountdownText?.apply {\n      text = \"HOUR  ${clockStamp(remaining)}\"\n      setTextColor(when {\n        remaining in 1L..10L -> Color.rgb(227, 83, 96)\n        remaining in 11L..60L -> Color.rgb(215, 165, 68)\n        remaining == 0L -> Color.rgb(111, 208, 141)\n        else -> Color.rgb(244, 245, 246)\n      })\n    }\n  }\n\n  private fun renderCooldownStrip(drugSeconds: Int, boosterSeconds: Int, medicalSeconds: Int) {\n    fun update(view: TextView?, seconds: Int) {\n      val target = view ?: return\n      when {\n        seconds < 0 -> {\n          target.text = \"--\"\n          target.setTextColor(Color.rgb(170, 175, 181))\n        }\n        seconds == 0 -> {\n          target.text = \"READY\"\n          target.setTextColor(Color.rgb(111, 208, 141))\n        }\n        else -> {\n          target.text = formatDuration(seconds)\n          target.setTextColor(Color.rgb(236, 238, 240))\n        }\n      }\n    }\n    update(drugCooldownText, drugSeconds)\n    update(boosterCooldownText, boosterSeconds)\n    update(medicalCooldownText, medicalSeconds)\n    cooldownRowView?.visibility = if (hudCollapsed || !showCooldownStrip) View.GONE else View.VISIBLE\n  }\n\n  private fun renderEventTicker() {\n    val view = eventTickerText ?: return\n    if (hudCollapsed) {\n      view.visibility = View.GONE\n      return\n    }\n    val message = eventTickerMessage\n    if (message.isNullOrBlank() || SystemClock.elapsedRealtime() >= eventTickerUntilElapsed) {\n      view.visibility = View.GONE\n      return\n    }\n    view.text = \"⚠  ALERT  •  $message\"\n    view.setTextColor(eventTickerColor)\n    view.background = GradientDrawable().apply {\n      shape = GradientDrawable.RECTANGLE\n      cornerRadius = dp(8).toFloat()\n      setColor(Color.argb(220, 36, 31, 34))\n      setStroke(dp(1), Color.argb(205, Color.red(eventTickerColor), Color.green(eventTickerColor), Color.blue(eventTickerColor)))\n    }\n    view.visibility = View.VISIBLE\n  }\n\n  private fun formatAge(totalSeconds: Int): String {\n    if (totalSeconds < 10) return \"JUST NOW\"\n    if (totalSeconds < 60) return \"${totalSeconds}s AGO\"\n    val minutes = totalSeconds / 60\n    if (minutes < 60) return \"${minutes}m AGO\"\n    val hours = minutes / 60\n    if (hours < 24) return \"${hours}h AGO\"\n    return \"${hours / 24}d AGO\"\n  }\n\n  private fun formatDuration(totalSeconds: Int): String {\n    if (totalSeconds <= 0) return \"READY\"\n    val hours = totalSeconds / 3600\n    val minutes = (totalSeconds % 3600) / 60\n    val seconds = totalSeconds % 60\n    return when {\n      hours > 0 -> \"${hours}h ${minutes}m\"\n      minutes > 0 -> \"${minutes}m ${seconds}s\"\n      else -> \"${seconds}s\"\n    }\n  }\n\n  private fun dp(value: Int): Int = (value * resources.displayMetrics.density).toInt()\n}\n";
const STORAGE_JS = "import * as SecureStore from 'expo-secure-store';\n\nconst API_KEY = 'comfortable_ai_torn_api_key';\nconst SETTINGS_KEY = 'comfortable_ai_settings';\n\nexport const DEFAULT_SETTINGS = {\n  energyWarningMinutes: 15,\n  nerveWarningMinutes: 15,\n  cooldownAlerts: true,\n  statusAlerts: true,\n  attackAlerts: true,\n  hudPreset: 'standard',\n  hudOpacity: 0.92,\n  hudShowTctClock: true,\n  hudShowHourCountdown: true,\n  hudShowBarTimers: true,\n  hudShowCooldowns: true,\n  hudPositionLocked: false,\n};\n\nexport async function saveApiKey(value) { await SecureStore.setItemAsync(API_KEY, value); }\nexport async function getApiKey() { return SecureStore.getItemAsync(API_KEY); }\nexport async function clearApiKey() { await SecureStore.deleteItemAsync(API_KEY); }\nexport async function loadSettings() {\n  try {\n    const raw = await SecureStore.getItemAsync(SETTINGS_KEY);\n    return raw ? {...DEFAULT_SETTINGS, ...JSON.parse(raw)} : {...DEFAULT_SETTINGS};\n  } catch { return {...DEFAULT_SETTINGS}; }\n}\nexport async function saveSettings(settings) { await SecureStore.setItemAsync(SETTINGS_KEY, JSON.stringify(settings)); }\n";

setEmbedded('APP_JS', APP_JS);
setEmbedded('OVERLAY_MODULE_KT', OVERLAY_MODULE_KT);
setEmbedded('OVERLAY_SERVICE_KT', OVERLAY_SERVICE_KT);

// Keep the JS source used by Metro in lockstep with the native HUD preferences.
fs.writeFileSync('App.js', APP_JS, 'utf8');
fs.writeFileSync('storage.js', STORAGE_JS, 'utf8');
fs.mkdirSync('src', {recursive:true});
fs.writeFileSync('src/storage.js', STORAGE_JS, 'utf8');

fs.writeFileSync(FILE, src, 'utf8');
console.log('\nTornPulse HUD settings + persistence applied successfully.');
